import{_ as e,r as n,o,c,e as s,a as l,s as i}from"./chunks/framework.CXcwiNg-.js";const v=JSON.parse('{"title":"{% partial %} - October CMS - 3.x","titleTemplate":false,"description":"Twig-тег","frontmatter":{"subtitle":"Twig-тег"},"headers":[{"level":2,"title":"Переменные","slug":"переменные","link":"#переменные","children":[]},{"level":2,"title":"Передача разметки как переменной","slug":"передача-разметки-как-переменнои","link":"#передача-разметки-как-переменнои","children":[{"level":3,"title":"Составные фрагменты","slug":"составные-фрагменты","link":"#составные-фрагменты","children":[]}]},{"level":2,"title":"Сохранение содержимого фрагмента в Twig-переменную","slug":"сохранение-содержимого-фрагмента-в-twig-переменную","link":"#сохранение-содержимого-фрагмента-в-twig-переменную","children":[]},{"level":2,"title":"Проверка существования фрагмента","slug":"проверка-существования-фрагмента","link":"#проверка-существования-фрагмента","children":[]}],"relativePath":"3.x/ru/markup/tag/partial.md","filePath":"3.x/ru/markup/tag/partial.md"}'),u={name:"3.x/ru/markup/tag/partial.md"};function g(r,a,k,d,w,m){const t=n("pre-heading"),p=n("post-heading");return o(),c("div",null,[s(t),a[0]||(a[0]=l("h1",null,"{% partial %}",-1)),s(p),a[1]||(a[1]=i(`<p>Тег <code>{% partial %}</code> парсит <a href="./../../cms/themes/partials.html">CMS-фрагмент</a> и рендерит его содержимое на странице. Чтобы отобразить фрагмент с именем <strong>footer.htm</strong>, просто передайте имя после тега <code>partial</code> в кавычках как строку.</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">partial</span> <span class="token string"><span class="token punctuation">&quot;</span>footer<span class="token punctuation">&quot;</span></span> <span class="token delimiter punctuation">%}</span></span>
</code></pre></div><p>Фрагмент в поддиректории рендерится аналогичным образом.</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">partial</span> <span class="token string"><span class="token punctuation">&quot;</span>sidebar/menu<span class="token punctuation">&quot;</span></span> <span class="token delimiter punctuation">%}</span></span>
</code></pre></div><div class="custom-block tip"><p><a href="./../../cms/themes/themes.html">Документация по темам</a> содержит подробности об использовании поддиректорий.</p></div><p>Имя фрагмента также может быть переменной:</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">set</span> tabName <span class="token operator">=</span> <span class="token string"><span class="token punctuation">&quot;</span>profile<span class="token punctuation">&quot;</span></span> <span class="token delimiter punctuation">%}</span></span>
<span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">partial</span> tabName <span class="token delimiter punctuation">%}</span></span>
</code></pre></div><h2 id="переменные"><a href="#переменные" class="header-anchor">#</a> Переменные</h2><p>Вы можете передавать переменные во фрагменты, указав их после имени фрагмента:</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">partial</span> <span class="token string"><span class="token punctuation">&quot;</span>blog-posts<span class="token punctuation">&quot;</span></span> posts<span class="token operator">=</span>posts <span class="token delimiter punctuation">%}</span></span>
</code></pre></div><p>Вы также можете назначать новые переменные для использования во фрагменте:</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">partial</span> <span class="token string"><span class="token punctuation">&quot;</span>location<span class="token punctuation">&quot;</span></span> city<span class="token operator">=</span><span class="token string"><span class="token punctuation">&quot;</span>Vancouver<span class="token punctuation">&quot;</span></span> country<span class="token operator">=</span><span class="token string"><span class="token punctuation">&quot;</span>Canada<span class="token punctuation">&quot;</span></span> <span class="token delimiter punctuation">%}</span></span>
</code></pre></div><p>Внутри фрагмента к переменным можно обращаться как к любой другой переменной разметки:</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>p</span><span class="token punctuation">&gt;</span></span>Country: <span class="token twig language-twig"><span class="token delimiter punctuation">{{</span> country <span class="token delimiter punctuation">}}</span></span>, city: <span class="token twig language-twig"><span class="token delimiter punctuation">{{</span> city <span class="token delimiter punctuation">}}</span></span>.<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>p</span><span class="token punctuation">&gt;</span></span>
</code></pre></div><h2 id="передача-разметки-как-переменнои"><a href="#передача-разметки-как-переменнои" class="header-anchor">#</a> Передача разметки как переменной</h2><p>Можно передать разметку во фрагмент с помощью атрибута <code>body</code>.</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">partial</span> <span class="token string"><span class="token punctuation">&quot;</span>card<span class="token punctuation">&quot;</span></span> body <span class="token delimiter punctuation">%}</span></span>
    This is the card contents
<span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">endpartial</span> <span class="token delimiter punctuation">%}</span></span>
</code></pre></div><p>Содержимое затем доступно как переменная <code>body</code>.</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{{</span> body<span class="token operator">|</span>raw <span class="token delimiter punctuation">}}</span></span>
</code></pre></div><h3 id="составные-фрагменты"><a href="#составные-фрагменты" class="header-anchor">#</a> Составные фрагменты</h3><p>Составные фрагменты возможны в сочетании с <a href="./placeholder.html">Twig-тегом</a> <code>{% placeholder %}</code>. Следующий фрагмент определяет секции <code>header</code> и <code>body</code>, куда можно добавлять HTML-контент.</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>div</span> <span class="token attr-name">class</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>header<span class="token punctuation">&quot;</span></span><span class="token punctuation">&gt;</span></span>
    <span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">placeholder</span> header <span class="token delimiter punctuation">%}</span></span>
<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>div</span><span class="token punctuation">&gt;</span></span>
<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>div</span> <span class="token attr-name">class</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>body<span class="token punctuation">&quot;</span></span><span class="token punctuation">&gt;</span></span>
    <span class="token twig language-twig"><span class="token delimiter punctuation">{{</span> body<span class="token operator">|</span>raw <span class="token delimiter punctuation">}}</span></span>
<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>div</span><span class="token punctuation">&gt;</span></span>
</code></pre></div><p>Далее вы можете включить тег <code>{% put %}</code> внутри <code>body</code>, чтобы составить результат фрагмента с двумя секциями HTML-контента.</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">partial</span> <span class="token string"><span class="token punctuation">&quot;</span>card<span class="token punctuation">&quot;</span></span> body <span class="token delimiter punctuation">%}</span></span>
    <span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">put</span> header <span class="token delimiter punctuation">%}</span></span>
        <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>h2</span><span class="token punctuation">&gt;</span></span>This is the card header<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>h2</span><span class="token punctuation">&gt;</span></span>
    <span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">endput</span> <span class="token delimiter punctuation">%}</span></span>
    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>p</span><span class="token punctuation">&gt;</span></span>This is the card contents<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>p</span><span class="token punctuation">&gt;</span></span>
<span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">endpartial</span> <span class="token delimiter punctuation">%}</span></span>
</code></pre></div><h2 id="сохранение-содержимого-фрагмента-в-twig-переменную"><a href="#сохранение-содержимого-фрагмента-в-twig-переменную" class="header-anchor">#</a> Сохранение содержимого фрагмента в Twig-переменную</h2><p>В любом шаблоне вы можете сохранить содержимое фрагмента в переменную с помощью функции <code>partial()</code>. Это позволяет манипулировать выводом перед отображением. Не забудьте использовать фильтр <code>|raw</code>, чтобы предотвратить экранирование вывода.</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">set</span> cardPartial <span class="token operator">=</span> partial<span class="token punctuation">(</span><span class="token string"><span class="token punctuation">&#39;</span>my-cards/card<span class="token punctuation">&#39;</span></span><span class="token punctuation">)</span> <span class="token delimiter punctuation">%}</span></span>

<span class="token twig language-twig"><span class="token delimiter punctuation">{{</span> cardPartial<span class="token operator">|</span>raw <span class="token delimiter punctuation">}}</span></span>
</code></pre></div><p>Вы также можете передать переменные во фрагмент как второй аргумент.</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">set</span> cardPartial <span class="token operator">=</span> partial<span class="token punctuation">(</span><span class="token string"><span class="token punctuation">&#39;</span>my-cards/card<span class="token punctuation">&#39;</span></span><span class="token punctuation">,</span> <span class="token punctuation">{</span> foo<span class="token punctuation">:</span> <span class="token string"><span class="token punctuation">&#39;</span>bar<span class="token punctuation">&#39;</span></span> <span class="token punctuation">}</span><span class="token punctuation">)</span> <span class="token delimiter punctuation">%}</span></span>
</code></pre></div><h2 id="проверка-существования-фрагмента"><a href="#проверка-существования-фрагмента" class="header-anchor">#</a> Проверка существования фрагмента</h2><p>Функция <code>hasPartial()</code> может использоваться для проверки существования фрагмента без рендеринга содержимого — она вернёт true или false в зависимости от того, найден ли фрагмент.</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">if</span> hasPartial<span class="token punctuation">(</span><span class="token string"><span class="token punctuation">&#39;</span>my-cards/card<span class="token punctuation">&#39;</span></span><span class="token punctuation">)</span> <span class="token delimiter punctuation">%}</span></span>
    <span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">partial</span> <span class="token string"><span class="token punctuation">&#39;</span>my-cards/card<span class="token punctuation">&#39;</span></span> <span class="token delimiter punctuation">%}</span></span>
<span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">else</span> <span class="token delimiter punctuation">%}</span></span>
    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>p</span><span class="token punctuation">&gt;</span></span>Card not found!<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>p</span><span class="token punctuation">&gt;</span></span>
<span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">endif</span> <span class="token delimiter punctuation">%}</span></span>
</code></pre></div>`,32))])}const y=e(u,[["render",g]]);export{v as __pageData,y as default};
